namespace ghidra.app.plugin.core.compositeeditor;






using docking;
using docking.action;
using generic.theme;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

public class DeleteAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Delete Components";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static Icon ICON = new GIcon("icon.plugin.composite.editor.delete");
	private static string[] popupPath = new string[] { "Delete" };
	private static KeyStroke KEY_STROKE = KeyStroke.getKeyStroke(KeyEvent.VK_DELETE, 0);

	public DeleteAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, popupPath, null, ICON)
    {

		setKeyBindingData(new KeyBindingData(KEY_STROKE));
		setDescription("Delete the selected components");
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		TaskLauncher.launchModal(getName(), this.doDelete);
		requestTableFocus();
	}

	private void doDelete(TaskMonitor monitor) {
		try {
			model.deleteSelectedComponents();
		}
		catch (CancelledException e) {
			// user cancelled
		}
		catch (UsrException e) {
			model.setStatus(e.getMessage(), true);
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isDeleteAllowed();
	}

}
